$out="$env:TEMP\ov_probe"; @'
import fs from "fs";
const sid="dsh-session-fe39d020-d16c-4d40-bb47-f0f5a1b5d781";
const r=await fetch(`http://127.0.0.1:1933/api/v1/sessions/${sid}/commit`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({keep_recent_count:0})});
const j=await r.json();
console.log("COMMIT",r.status, JSON.stringify(j.result||j).slice(0,400));
fs.writeFileSync(process.argv[2], (j.result?.task_id)||"","utf8");
'@ | Set-Content "$out\cm.mjs" -Encoding UTF8; node "$out\cm.mjs" "$out\taskid2.txt"
